insert into event (
  slug,
  title,
  summary,
  occurred_on,
  occurred_on_precision,
  location_text,
  location_country_code,
  developer_or_operator,
  system_name,
  automation_status,
  system_version,
  system_version_knowledge,
  event_type,
  valence,
  observed_facts,
  unknowns,
  interpretation,
  causation_status,
  causation_note,
  review_status,
  record_updated
)
select
  slug,
  title,
  summary,
  occurred_on::date,
  occurred_on_precision,
  location_text::text,
  location_country_code::text,
  developer_or_operator,
  system_name::text,
  automation_status,
  system_version::text,
  system_version_knowledge,
  event_type,
  valence,
  observed_facts::text[],
  unknowns::text[],
  interpretation::text,
  causation_status,
  causation_note::text,
  review_status,
  record_updated::date
from seed
on conflict (slug) do update set
  title = excluded.title,
  summary = excluded.summary,
  occurred_on = excluded.occurred_on,
  occurred_on_precision = excluded.occurred_on_precision,
  location_text = excluded.location_text,
  location_country_code = excluded.location_country_code,
  developer_or_operator = excluded.developer_or_operator,
  system_name = excluded.system_name,
  automation_status = excluded.automation_status,
  system_version = excluded.system_version,
  system_version_knowledge = excluded.system_version_knowledge,
  event_type = excluded.event_type,
  valence = excluded.valence,
  observed_facts = excluded.observed_facts,
  unknowns = excluded.unknowns,
  interpretation = excluded.interpretation,
  causation_status = excluded.causation_status,
  causation_note = excluded.causation_note,
  review_status = excluded.review_status,
  record_updated = excluded.record_updated
where
  event.title is distinct from excluded.title
  or event.summary is distinct from excluded.summary
  or event.occurred_on is distinct from excluded.occurred_on
  or event.occurred_on_precision is distinct from excluded.occurred_on_precision
  or event.location_text is distinct from excluded.location_text
  or event.location_country_code is distinct from excluded.location_country_code
  or event.developer_or_operator is distinct from excluded.developer_or_operator
  or event.system_name is distinct from excluded.system_name
  or event.automation_status is distinct from excluded.automation_status
  or event.system_version is distinct from excluded.system_version
  or event.system_version_knowledge is distinct from excluded.system_version_knowledge
  or event.event_type is distinct from excluded.event_type
  or event.valence is distinct from excluded.valence
  or event.observed_facts is distinct from excluded.observed_facts
  or event.unknowns is distinct from excluded.unknowns
  or event.interpretation is distinct from excluded.interpretation
  or event.causation_status is distinct from excluded.causation_status
  or event.causation_note is distinct from excluded.causation_note
  or event.review_status is distinct from excluded.review_status
  or event.record_updated is distinct from excluded.record_updated;

