insert into event_source (
  event_id,
  url,
  source_type,
  publisher,
  label,
  published_on,
  published_on_precision,
  retrieved_on,
  note
)
select
  e.id,
  s.url,
  s.source_type,
  s.publisher::text,
  s.label::text,
  s.published_on::date,
  s.published_on_precision,
  s.retrieved_on::date,
  s.note::text
from seed_source s
join event e on e.slug = s.event_slug
on conflict (event_id, url) do update set
  source_type = excluded.source_type,
  publisher = excluded.publisher,
  label = excluded.label,
  published_on = excluded.published_on,
  published_on_precision = excluded.published_on_precision,
  retrieved_on = excluded.retrieved_on,
  note = excluded.note
where
  event_source.source_type is distinct from excluded.source_type
  or event_source.publisher is distinct from excluded.publisher
  or event_source.label is distinct from excluded.label
  or event_source.published_on is distinct from excluded.published_on
  or event_source.published_on_precision is distinct from excluded.published_on_precision
  or event_source.retrieved_on is distinct from excluded.retrieved_on
  or event_source.note is distinct from excluded.note;

-- ---------------------------------------------------------------------------
-- publish — the ONLY path to is_public = true. Runs after the sources exist,
-- so the database invariant "a public event has >= 1 source" holds. Idempotent:
-- once public the WHERE matches nothing and first_published_at is never
-- re-stamped.
-- ---------------------------------------------------------------------------
